import os
from typing import Any, Dict, List, Union

import boto3


def extract_table_cells_and_rows(
    document: Union[str, bytes],
    region_name: str = None,
    table_index: int = 0,
) -> Dict[str, Any]:
    """
    Extract table cells and row structure from a document using Amazon Textract.

    Args:
        document: Path to a local file or raw bytes of the document/image.
        region_name: Optional AWS region for Textract.
        table_index: Which detected table to extract if multiple tables exist.

    Returns:
        A dictionary with tables, each containing rows and cells in reading order.
    """
    textract = boto3.client("textract", region_name=region_name or os.getenv("AWS_REGION"))

    if isinstance(document, str):
        with open(document, "rb") as f:
            payload = f.read()
    else:
        payload = document

    response = textract.analyze_document(
        Document={"Bytes": payload},
        FeatureTypes=["TABLES"],
    )

    blocks = response.get("Blocks", [])
    block_map = {block["Id"]: block for block in blocks if "Id" in block}

    table_blocks = [b for b in blocks if b.get("BlockType") == "TABLE"]
    if not table_blocks:
        return {"tables": []}

    extracted_tables: List[Dict[str, Any]] = []

    for tbl_idx, table in enumerate(table_blocks):
        if tbl_idx != table_index:
            continue

        cell_ids = table.get("Relationships", [])
        all_cell_ids: List[str] = []
        for rel in cell_ids:
            if rel.get("Type") == "CHILD":
                all_cell_ids.extend(rel.get("Ids", []))

        cells = []
        for cid in all_cell_ids:
            cell = block_map.get(cid)
            if not cell or cell.get("BlockType") != "CELL":
                continue

            row_index = cell.get("RowIndex")
            col_index = cell.get("ColumnIndex")
            row_span = cell.get("RowSpan", 1)
            col_span = cell.get("ColumnSpan", 1)

            text = _collect_text(cell, block_map)
            cells.append(
                {
                    "row_index": row_index,
                    "column_index": col_index,
                    "row_span": row_span,
                    "column_span": col_span,
                    "text": text,
                    "confidence": cell.get("Confidence"),
                    "geometry": cell.get("Geometry"),
                }
            )

        rows: Dict[int, List[Dict[str, Any]]] = {}
        for cell in cells:
            rows.setdefault(cell["row_index"], []).append(cell)

        structured_rows = []
        for row_index in sorted(rows.keys()):
            row_cells = sorted(rows[row_index], key=lambda c: (c["column_index"], c["row_index"]))
            structured_rows.append({"row_index": row_index, "cells": row_cells})

        extracted_tables.append(
            {
                "table_index": tbl_idx,
                "rows": structured_rows,
                "cells": sorted(cells, key=lambda c: (c["row_index"], c["column_index"])),
            }
        )

    return {"tables": extracted_tables}


def _collect_text(block: Dict[str, Any], block_map: Dict[str, Dict[str, Any]]) -> str:
    parts: List[str] = []
    for rel in block.get("Relationships", []):
        if rel.get("Type") != "CHILD":
            continue
        for child_id in rel.get("Ids", []):
            child = block_map.get(child_id)
            if not child:
                continue
            block_type = child.get("BlockType")
            if block_type == "WORD":
                parts.append(child.get("Text", ""))
            elif block_type == "SELECTION_ELEMENT":
                if child.get("SelectionStatus") == "SELECTED":
                    parts.append("X")
    return " ".join(part for part in parts if part).strip()
